    book_sells = []  # list of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    arrival_counter = 0
    order_states = {}  # id -> {'type': 'limit'|'ioc'|'market', 'remaining_qty': int}

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_states:
                # Remove from book
                book_buys[:] = [(p, t, oid, q) for p, t, oid, q in book_buys if oid != order_id]
